using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;
namespace DesktopBox {
public static class RecycleEntry {
 [ComImport,Guid("43826D1E-E718-42EE-BC55-A1E261C37BFE"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]public interface ShellItem {void BindToHandler(IntPtr context,ref Guid handler,ref Guid iid,out IntPtr value);void GetParent(out ShellItem parent);void GetDisplayName(uint kind,out IntPtr text);void GetAttributes(uint mask,out uint attributes);void Compare(ShellItem other,uint hint,out int order);}
 [ComImport,Guid("947AAB5F-0A5C-4C13-B4D6-4BF7836FC9F8"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface FileOperation {
  void Advise(ProgressSink sink,out uint cookie);void Unadvise(uint cookie);void SetOperationFlags(uint flags);void SetProgressMessage([MarshalAs(UnmanagedType.LPWStr)]string text);void SetProgressDialog([MarshalAs(UnmanagedType.Interface)]object dialog);void SetProperties([MarshalAs(UnmanagedType.Interface)]object properties);void SetOwnerWindow(IntPtr window);void ApplyPropertiesToItem(ShellItem item);void ApplyPropertiesToItems([MarshalAs(UnmanagedType.Interface)]object items);void RenameItem(ShellItem item,[MarshalAs(UnmanagedType.LPWStr)]string name,ProgressSink sink);void RenameItems([MarshalAs(UnmanagedType.Interface)]object items,[MarshalAs(UnmanagedType.LPWStr)]string name);void MoveItem(ShellItem item,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name,ProgressSink sink);void MoveItems([MarshalAs(UnmanagedType.Interface)]object items,ShellItem folder);void CopyItem(ShellItem item,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name,ProgressSink sink);void CopyItems([MarshalAs(UnmanagedType.Interface)]object items,ShellItem folder);void DeleteItem(ShellItem item,ProgressSink sink);void DeleteItems([MarshalAs(UnmanagedType.Interface)]object items);void NewItem(ShellItem folder,uint attributes,[MarshalAs(UnmanagedType.LPWStr)]string name,[MarshalAs(UnmanagedType.LPWStr)]string template,ProgressSink sink);void PerformOperations();void GetAnyOperationsAborted([MarshalAs(UnmanagedType.Bool)]out bool aborted);
 }
 [ComVisible(true),Guid("04B0F1A7-9490-44BC-96E1-4296A31252E2"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]public interface ProgressSink {
  [PreserveSig]int StartOperations();[PreserveSig]int FinishOperations(int result);[PreserveSig]int PreRenameItem(uint flags,ShellItem item,[MarshalAs(UnmanagedType.LPWStr)]string name);[PreserveSig]int PostRenameItem(uint flags,ShellItem item,[MarshalAs(UnmanagedType.LPWStr)]string name,int result,ShellItem created);[PreserveSig]int PreMoveItem(uint flags,ShellItem item,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name);[PreserveSig]int PostMoveItem(uint flags,ShellItem item,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name,int result,ShellItem created);[PreserveSig]int PreCopyItem(uint flags,ShellItem item,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name);[PreserveSig]int PostCopyItem(uint flags,ShellItem item,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name,int result,ShellItem created);[PreserveSig]int PreDeleteItem(uint flags,ShellItem item);[PreserveSig]int PostDeleteItem(uint flags,ShellItem item,int result,ShellItem created);[PreserveSig]int PreNewItem(uint flags,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name);[PreserveSig]int PostNewItem(uint flags,ShellItem folder,[MarshalAs(UnmanagedType.LPWStr)]string name,[MarshalAs(UnmanagedType.LPWStr)]string template,uint attributes,int result,ShellItem created);[PreserveSig]int UpdateProgress(uint total,uint completed);[PreserveSig]int ResetTimer();[PreserveSig]int PauseTimer();[PreserveSig]int ResumeTimer();
 }
 [ComVisible(true),ClassInterface(ClassInterfaceType.None)]public sealed class Sink:ProgressSink {
  public bool Recycled,Posted;public int Result;public uint PreFlags;public string Destination="";
  public int PreDeleteItem(uint flags,ShellItem item){PreFlags=flags;return (flags&0x80)!=0?0:unchecked((int)0x80004004);}
  public int PostDeleteItem(uint flags,ShellItem item,int result,ShellItem created){Posted=true;Result=result;Recycled=result>=0&&created!=null;if(Recycled){IntPtr text=IntPtr.Zero;try{created.GetDisplayName(0x80058000,out text);Destination=Marshal.PtrToStringUni(text)??"";}catch{}finally{if(text!=IntPtr.Zero)Marshal.FreeCoTaskMem(text);}}return 0;}
  public int StartOperations(){return 0;}public int FinishOperations(int result){return 0;}public int PreRenameItem(uint f,ShellItem i,string n){return 0;}public int PostRenameItem(uint f,ShellItem i,string n,int r,ShellItem c){return 0;}public int PreMoveItem(uint f,ShellItem i,ShellItem d,string n){return 0;}public int PostMoveItem(uint f,ShellItem i,ShellItem d,string n,int r,ShellItem c){return 0;}public int PreCopyItem(uint f,ShellItem i,ShellItem d,string n){return 0;}public int PostCopyItem(uint f,ShellItem i,ShellItem d,string n,int r,ShellItem c){return 0;}public int PreNewItem(uint f,ShellItem i,string n){return 0;}public int PostNewItem(uint f,ShellItem i,string n,string t,uint a,int r,ShellItem c){return 0;}public int UpdateProgress(uint t,uint c){return 0;}public int ResetTimer(){return 0;}public int PauseTimer(){return 0;}public int ResumeTimer(){return 0;}
 }
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,PreserveSig=false)]static extern void SHCreateItemFromParsingName(string path,IntPtr context,ref Guid iid,out ShellItem item);
 public const uint OperationFlags=0x00080000|0x20000000|0x0040|0x0400|0x00100000|0x4000|0x0004|0x0010;
 public sealed class Result {public string Path,Destination;public bool Directory;public uint Flags,PreFlags;public string Time;}
 public static string Unavailable(string path){try{if(EntryPath.IsShell(path))return "系统入口不能作为文件删除";if(String.IsNullOrWhiteSpace(path))return "入口为空";string full=System.IO.Path.GetFullPath(path);string root=System.IO.Path.GetPathRoot(full);if(full.TrimEnd('\\').Equals(root.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))return "不能将整个磁盘移到回收站";if(full.StartsWith(@"\\")||new DriveInfo(root).DriveType!=DriveType.Fixed)return "此位置不支持安全移到本机回收站";if(!File.Exists(full)&&!System.IO.Directory.Exists(full))return "文件已不存在";for(string part=full;!String.IsNullOrEmpty(part)&&part.Length>root.Length;part=System.IO.Path.GetDirectoryName(part)){if((File.GetAttributes(part)&FileAttributes.ReparsePoint)!=0)return "链接或挂载目录请在资源管理器中处理";}return "";}catch(Exception ex){return ex.Message;}}
 public static Result Send(string path,IntPtr owner){string reason=Unavailable(path);if(reason!="")throw new InvalidOperationException(reason);string full=System.IO.Path.GetFullPath(path);bool directory=System.IO.Directory.Exists(full);object instance=null;ShellItem item=null;var sink=new Sink();try{instance=Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("3AD05575-8857-4850-9277-11B85BDB8E09")));var operation=(FileOperation)instance;operation.SetOwnerWindow(owner);operation.SetOperationFlags(OperationFlags);Guid iid=typeof(ShellItem).GUID;SHCreateItemFromParsingName(full,IntPtr.Zero,ref iid,out item);operation.DeleteItem(item,sink);operation.PerformOperations();bool aborted;operation.GetAnyOperationsAborted(out aborted);if(aborted)throw new OperationCanceledException("已取消移到回收站");if(sink.Posted&&sink.Result<0)Marshal.ThrowExceptionForHR(sink.Result);if(!sink.Recycled||File.Exists(full)||System.IO.Directory.Exists(full))throw new IOException("系统未确认文件已移到回收站，收纳入口保留");return new Result{Path=full,Destination=sink.Destination,Directory=directory,Flags=OperationFlags,PreFlags=sink.PreFlags,Time=DateTimeOffset.Now.ToString("o")};}finally{GC.KeepAlive(sink);if(item!=null&&Marshal.IsComObject(item))Marshal.ReleaseComObject(item);if(instance!=null&&Marshal.IsComObject(instance))Marshal.ReleaseComObject(instance);}}
 public static void RemoveEntries(Model model,string path,bool directory){string full=System.IO.Path.GetFullPath(path).TrimEnd('\\');model.Items.RemoveAll(i=>{if(EntryPath.IsShell(i.Path))return false;try{string candidate=System.IO.Path.GetFullPath(i.Path).TrimEnd('\\');return String.Equals(candidate,full,StringComparison.OrdinalIgnoreCase)||(directory&&candidate.StartsWith(full+"\\",StringComparison.OrdinalIgnoreCase));}catch{return false;}});model.DockPins.RemoveAll(id=>!model.Items.Any(i=>i.Id==id));}
}
